eyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE类型&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `glue_source` mediumtext COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE源代码&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `glue_remark` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;128&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;GLUE备注&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `add_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `update_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_registry` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `registry_group` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `registry_key` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `registry_value` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `update_time` datetime &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  KEY `i_g_k_v` (`registry_group`,`registry_key`,`registry_value`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_group` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `app_name` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;64&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器AppName&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `title` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器名称&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `address_type` tinyint(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;0&#39;&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器地址类型：0=自动注册、1=手动录入&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `address_list` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;512&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;执行器地址列表，多地址逗号分隔&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_user` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `id` &lt;span class=&#34;type&#34;&gt;int&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; AUTO_INCREMENT,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `username` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;账号&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `password` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;密码&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `role` tinyint(&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;角色：0-普通用户、1-管理员&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `permission` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;255&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;权限：执行器ID列表，多个逗号分割&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`id`),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;UNIQUE&lt;/span&gt; KEY `i_username` (`username`) &lt;span class=&#34;keyword&#34;&gt;USING&lt;/span&gt; BTREE&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;CREATE TABLE&lt;/span&gt; `xxl_job_lock` (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  `lock_name` &lt;span class=&#34;type&#34;&gt;varchar&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;50&lt;/span&gt;) &lt;span class=&#34;keyword&#34;&gt;NOT NULL&lt;/span&gt; COMMENT &lt;span class=&#34;string&#34;&gt;&#39;锁名称&#39;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;PRIMARY KEY&lt;/span&gt; (`lock_name`)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;) ENGINE&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;InnoDB &lt;span class=&#34;keyword&#34;&gt;DEFAULT&lt;/span&gt; CHARSET&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;utf8mb4;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;INSERT INTO&lt;/span&gt; `xxl_job_group`(`id`, `app_name`, `title`, `address_type`, `address_list`) &lt;span class=&#34;keyword&#34;&gt;VALUES&lt;/span&gt; (&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;xxl-job-executor-sample&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;示例执行器&#39;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;INSERT INTO&lt;/span&gt; `xxl_job_info`(`id`, `job_group`, `job_cron`, `job_desc`, `add_time`, `update_time`, `author`, `alarm_email`, `executor_route_strategy`, `executor_handler`, `executor_param`, `executor_block_strategy`, `executor_timeout`, `executor_fail_retry_count`, `glue_type`, `glue_source`, `glue_remark`, `glue_updatetime`, `child_jobid`) &lt;span class=&#34;keyword&#34;&gt;VALUES&lt;/span&gt; (&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;0 0 0 * * ? *&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;测试任务1&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;2018-11-03 22:21:31&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;2018-11-03 22:21:31&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;XXL&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;FIRST&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;demoJobHandler&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;SERIAL_EXECUTION&#39;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;BEAN&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;GLUE代码初始化&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;2018-11-03 22:21:31&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;&#39;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;INSERT INTO&lt;/span&gt; `xxl_job_user`(`id`, `username`, `password`, `role`, `permission`) &lt;span class=&#34;keyword&#34;&gt;VALUES&lt;/span&gt; (&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;admin&#39;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&#39;e10adc3949ba59abbe56e057f20f883e&#39;&lt;/span&gt;, &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;keyword&#34;&gt;NULL&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;INSERT INTO&lt;/span&gt; `xxl_job_lock` ( `lock_name`) &lt;span class=&#34;keyword&#34;&gt;VALUES&lt;/span&gt; ( &lt;span class=&#34;string&#34;&gt;&#39;schedule_lock&#39;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;commit&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;docker-compose.yml&lt;/p&gt;
&lt;figure class=&#34;highlight yaml&#34;&gt;&lt;table&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;version:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#34;3&#34;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;services:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;xxl-job-admin:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;restart:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;always&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;image:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;xuxueli/xxl-job-admin:3.1.1&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;container_name:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;xxl-job-admin&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;volumes:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;./data/logs:/data/applogs&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;ports:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#34;11001:8800&#34;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;environment:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;attr&#34;&gt;PARAMS:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&#39;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --server.port=8800&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --server.servlet.context-path=/xxl-job-admin&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --spring.datasource.url=jdbc:mysql://192.168.11.122:3306/xxl_job?useUnicode=true&amp;amp;characterEncoding=UTF-8&amp;amp;autoReconnect=true&amp;amp;serverTimezone=Asia/Shanghai&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --spring.datasource.username=root&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --spring.datasource.password=mysql_XH8h7N&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;string&#34;&gt;      --xxl.job.accessToken=onelovehzs888&#39;&lt;/span&gt;  &lt;span class=&#34;comment&#34;&gt;#代码里面需要指定的token&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;启动&#34;&gt;&lt;a href=&#34;#启动&#34; class=&#34;headerlink&#34; title=&#34;启动&#34;&gt;&lt;/a&gt;启动&lt;/h2&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;docker-compose up -d&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;h2 id=&#34;访问&#34;&gt;&lt;a href=&#34;#访问&#34; class=&#34;headerlink&#34; title=&#34;访问&#34;&gt;&lt;/a&gt;访问&lt;/h2&gt;&lt;p&gt;&lt;a href=&#34;http://ip:11001/xxl-job-admin/&#34;&gt;http://ip:11001/xxl-job-admin/&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;默认用户名：admin&lt;br&gt;默认密码：123456&lt;/p&gt;
&lt;p&gt;效果图如下：&lt;br&gt;&lt;img src=&#34;https://ghproxy.imoyuapp.win/https://raw.githubusercontent.com/xubiaolin/picgo/master/cf13d9dfa61af2c2ed1629745ea3d098d65b09bb01e8a0962aaa1290b43d6f56.png&#34; alt=&#34;picture 1&#34;&gt;  &lt;/p&gt;
&lt;h1 id=&#34;参考链接&#34;&gt;&lt;a href=&#34;#参考链接&#34; class=&#34;headerlink&#34; title=&#34;参考链接&#34;&gt;&lt;/a&gt;参考链接&lt;/h1&gt;&lt;p&gt;&lt;a href=&#34;https://github.com/xuxueli/xxl-job/blob/master/doc/XXL-JOB%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3.md&#34;&gt;https://github.com/xuxueli/xxl-job/blob/master/doc/XXL-JOB%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3.md&lt;/a&gt;&lt;/p&gt;

 &lt;h1 id=&#34;前言&#34;&gt;&lt;a href=&#34;#前言&#34; class=&#34;headerlink&#34; title=&#34;前言&#34;&gt;&lt;/a&gt;前言&lt;/h1&gt;&lt;p&gt;之前申请了腾讯云的免费CDN, 尝试用来加速git page, 但是发现速度并不理想, 还是考虑将阿里云的域名迁移到Cloudflare.&lt;/p&gt;
&lt;h1 id=&#34;操作&#34;&gt;&lt;a href=&#34;#操作&#34; class=&#34;headerlink&#34; title=&#34;操作&#34;&gt;&lt;/a&gt;操作&lt;/h1&gt;&lt;h2 id=&#34;1-在Cloudflare中添加域名&#34;&gt;&lt;a href=&#34;#1-在Cloudflare中添加域名&#34; class=&#34;headerlink&#34; title=&#34;1. 在Cloudflare中添加域名&#34;&gt;&lt;/a&gt;1. 在Cloudflare中添加域名&lt;/h2&gt;&lt;p&gt;&lt;img src=&#34;https://raw.githubusercontent.com/xubiaolin/picgo/master/20250719020223544.png&#34;&gt;&lt;/p&gt;
&lt;p&gt;然后按照提示操作，这个时候会提示你修改DNS的地址&lt;/p&gt;
&lt;h2 id=&#34;2-修改DNS地址&#34;&gt;&lt;a href=&#34;#2-修改DNS地址&#34; class=&#34;headerlink&#34; title=&#34;2. 修改DNS地址&#34;&gt;&lt;/a&gt;2. 修改DNS地址&lt;/h2&gt;&lt;p&gt;&lt;img src=&#34;https://raw.githubusercontent.com/xubiaolin/picgo/master/20250719020434162.png&#34;&gt;&lt;/p&gt;
&lt;h2 id=&#34;3-等待Cloudflare生效&#34;&gt;&lt;a href=&#34;#3-等待Cloudflare生效&#34; class=&#34;headerlink&#34; title=&#34;3. 等待Cloudflare生效&#34;&gt;&lt;/a&gt;3. 等待Cloudflare生效&lt;/h2&gt;&lt;p&gt;&lt;img src=&#34;https://raw.githubusercontent.com/xubiaolin/picgo/master/20250719020554906.png&#34;&gt;&lt;/p&gt;
&lt;h1 id=&#34;原理解析&#34;&gt;&lt;a href=&#34;#原理解析&#34; class=&#34;headerlink&#34; title=&#34;原理解析&#34;&gt;&lt;/a&gt;原理解析&lt;/h1&gt;&lt;p&gt;在域名解析（DNS）体系中，DNS服务器负责告诉全世界“你的域名对应哪个IP地址”。当你将域名的DNS服务器（NS记录）修改为Cloudflare提供的DNS地址后，全球的DNS查询都会先到Cloudflare的DNS服务器获取解析结果。&lt;/p&gt;
&lt;p&gt;Cloudflare的DNS服务器会返回Cloudflare代理的IP地址（而不是你源站的真实IP），这样所有访问你域名的流量都会先经过Cloudflare的边缘节点，由Cloudflare进行加速、防护和缓存等处理后，再转发到你的源站服务器。这就是“走Cloudflare代理”的原理。&lt;/p&gt;
&lt;p&gt;简要流程如下：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;你在域名注册商处将NS记录改为Cloudflare提供的DNS服务器。&lt;/li&gt;
&lt;li&gt;访问者在访问你的域名时，DNS查询会到Cloudflare的DNS服务器获取IP。&lt;/li&gt;
&lt;li&gt;Cloudflare返回代理IP，访问者的请求先到Cloudflare节点。&lt;/li&gt;
&lt;li&gt;Cloudflare根据你的设置决定是否回源、缓存、拦截等。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;因此，只要把DNS服务器切换到Cloudflare，Cloudflare就能“接管”你的域名流量，实现全站加速和安全防护。&lt;/p&gt;
